from record import source as S, edge as E, replace as R, record as P

p='jonathan_israel';s='tq233_israel_bell2012';r='tq233_israel_lilti2009'
P(p,
'A historian of the Dutch Republic, European Jews and the Enlightenment whose radical-Enlightenment interpretation gives philosophical ideas a strong explanatory role. Israel’s interview argues that Spinoza’s reception helped create a radical current committed to equality and criticism of religious authority, opposed to a moderate Enlightenment. The proposed coherence and reach of that current are disputed. Antoine Lilti questions whether diverse heterodox writings can be treated as one Spinozist system. David Bell credits Israel’s range and insistence on ideas while challenging inferences from similar ideas to transmission, from polemical labels to actual belief, and from radical proposals to revolutionary causation. Bell invokes contextual intellectual history as a methodological contrast, not proof that Skinner personally answered Israel. These disagreements qualify the thesis’s explanatory priority; neither the historian’s confidence nor his critics’ objections are turned into disciplinary consensus.',
'Selected 2023 primary interview answers retained. Bell’s substantial review sections on unity, transmission, context and revolutionary causation read; Lilti’s displayed abstract and specified notes read, not full 2009 article. Complete selected books unread. Cambridge contextualist affiliation remains held; a specifically sourced comparison with its methodological cautions is proposed instead. No influence from shared ideas or dissertation counts.',
sources=[S(s,'David A. Bell, “Where Do We Come From?”, The New Republic, 2012: review of Democratic Enlightenment.','https://newrepublic.com/article/100556/spinoza-kant-enlightenment-ideas','Selected body from discussion of Israel’s unified Enlightenment through critique of transmission/context and revolutionary causation, including the Raynal passage, read. Bell’s praise and criticism both retained; originals he cites not independently read.'),S(r,'Antoine Lilti, “Comment écrit-on l’histoire intellectuelle des Lumières?”, Annales HSS 64:1 (2009): 171–206.','https://doi.org/10.1017/S0395264900028614','Displayed author abstract and notes 18–20 on importance, reception and coherence read. Challenges unity of radical Enlightenment and Spinozism as a tool; full article unread.')],
edges=[E(p,'context',p,'context','Bell contrasts Israel’s unified ideological genealogy with contextualist cautions about meaning, reception and retrospective influence claims.',s,'Bell, paragraphs beginning In writing history and A generation of intellectual historians, plus his transmission examples. Undirected methodological comparison; no Skinner-to-Israel personal dispute or school affiliation asserted.',kind='comparison')],
reads=[dict(source_id=s,locator='Specified substantial review sections, through Raynal context example'),dict(source_id=r,locator='Abstract and displayed nn. 18–20')],holds=['Lilti and Bell have no individual endpoints. Gay comparison reserved for batch 3; no generic Furet/Foucault critique inferred from insulting adjectives alone.'])

p='geoffrey_parker';s='tq233_parker_black2020';r='tq232_elliott_kaganparker2024'
P(p,
'A historian of early modern warfare and political power whose studies connect military organization, resources and the scale of states. The Army of Flanders began from a logistical question that Elliott encouraged and directed toward Febvre’s regional work; Parker’s own joint memoir supplies that account. His military-revolution interpretation broadens earlier tactical explanations, but the concept and its global reach remain disputed. Jeremy Black challenges Parker’s selective geographical evidence and the move from particular European examples to a worldwide paradigm; his polemic is a named criticism rather than a settled verdict. Rogers’s participant-editor account preserves a wider debate about chronology and mechanisms. Global Crisis later extends Parker’s research to the interaction of climatic pressures and seventeenth-century upheaval. That project is attributed to him without independent adoption of every causal or demographic estimate.',
'First-person Ohio State statement and earlier full Rogers introduction retained. Black’s published 2020 lecture outline read for methodological criticism; his personal attacks excluded. Kagan/Parker memoir pp. 231–234 read for Elliott’s specific research guidance. Complete selected books and original Febvre work unread. Black’s challenge is not universal scholarly rejection; Elliott’s guidance is not exclusive intellectual descent.',
sources=[S(s,'Jeremy Black, “Rethinking Military Revolutions,” The Critic, 20 January 2020.','https://thecritic.co.uk/rethinking-military-revolutions/','Published author lecture outline read, especially geographical/chronological selection and capability/context paragraphs. Specific criticism of Parker’s thesis; personal characterizations excluded. His other books and Parker’s 2019 lecture not newly read.')],existing=[r],
edges=[E(p,'elliott','john_h_elliott',p,'Elliott’s logistical question, reading guidance and supervision helped shape Parker’s Army of Flanders project.',r,'Kagan and Parker, memoir pp. 231–234, concrete recollection and quoted guidance on logistics, communications and wider implications. Parker is coauthor; letters/Febvre original not independently consulted.',kind='influence'),E(p,'black','jeremy_black',p,'Black challenges the geographical selectivity and global generalization of Parker’s military-revolution model.',s,'2020 outline, paragraphs beginning In my Beyond the Military Revolution and So also with Parker, plus subsequent contextual argument. Attributed methodological critique, not a fresh reading of all Black/Parker books.',kind='critique')],
reads=[dict(source_id=s,locator='Author’s published outline; specified methodological paragraphs'),dict(source_id=r,locator='Memoir pp. 231–234, with coauthor credit')],holds=['Roberts, Rogers and Febvre originals not freshly read. No claim that military revolution is either proven or unanimously discarded.'])

p='charles_s_maier';s='tq233_maier_interview2017';r='tq233_maier_ghil2013';m='tq233_maier_metadata2000'
P(p,
'A historian of modern Europe and the political organization of space. Maier treats territoriality as a historical resource: borders, sovereignty, technologies and institutions shape both decision-making and belonging. His interview explains why railways, telegraphs and other technologies matter without assuming that a networked world has abolished states. A conference report records Breuilly’s challenge to the coherence of an earlier “age of territoriality,” and Chatterjee’s account of colonial India’s overlapping sovereignties complicates any universal sequence. Maier’s own later account acknowledges more resistance to disappearing borders than he originally expected. His other research follows collective memory, trials and reparation after political violence. These are related inquiries into institutions and historical explanation, not a single prediction that globalization must dissolve political territory.',
'Entire displayed 2017 Weatherhead/Gazette interview and brief primary research statement read. GHIL conference report pp. 182–184 read, especially Maier/Breuilly/Chatterjee discussion; original talks unread. Harvard DASH cover/metadata establishes the 2000 AHR article, not a body reading: scanned text unavailable and local request rate-limited without retry. Full books unread. Hirschman is a named interview resource but lacks an individual endpoint; Pauline Maier’s American Scripture is not attributed to Charles.',
sources=[S(s,'Charles S. Maier, Weatherhead interview, “The Borders between Us,” Harvard Gazette, January 2017.','https://news.harvard.edu/gazette/story/2017/01/the-borders-between-us/','Complete displayed professional Q&A read from authorized institutional text, local receipt retained. Distinguishes interviewer framing, author arguments, uncertainty and future projects. Related original Weatherhead posting dated December 2016; no claim this is the 2000 article.'),S(r,'Thorsten Holzhauser and Andreas Lutsch, “The Territorial State after 1989,” GHIL Bulletin 35:2 (2013): 182–187.','https://www.ghil.ac.uk/fileadmin/redaktion/dokumente/bulletin/GHIL_Bulletin_35.2/GHIL%20Bulletin%2035%20%282013%29%2C2%20-%20182%20-%20Conference%20Reports%20-%20Territorial%20State.pdf','Selected printed pp. 182–184 read, especially the reported Maier opening, Breuilly objection and Chatterjee example. Conference-report mediation explicit; original talks and publications unread.'),S(m,'Charles S. Maier, “Consigning the Twentieth Century to History,” AHR 105:3 (2000): 807–831, Harvard DASH record.','https://dash.harvard.edu/entities/publication/73120378-8278-6bd4-e053-0100007fdf3b','Cover/metadata only: original AHR citation and DOI 10.2307/2651811. Scanned article body not read; local retrieval rate-limited and not retried.')],
edges=[E(p,'spatial',p,'spatialhistory','Treats territorial organization as a historical practice connecting authority, technologies, resources and belonging.',s,'Primary interview answers on a politics of space, territorial jurisdiction and network metaphors. Field contribution, not universal technological causation.'),E(p,'chatterjee',p,'partha_chatterjee','The reported conference discussion places Maier’s territorial periodization beside Chatterjee’s account of overlapping colonial sovereignties.',r,'GHIL pp. 183–184. Undirected, explicitly mediated comparison of approaches; no personal influence or verbatim original talk claimed.',kind='comparison')],
replacements=[R(p,1,p,'political','Investigates how control of bounded space, sovereignty and institutions organize political life.',s,'Primary interview answers on jurisdiction, borders and political organization; no simple disappearance-of-the-state thesis.',batch=2),R(p,2,p,'global','Examines changing territorial orders and technologies across connected societies without assuming a borderless endpoint.',s,'Primary interview on global history, communications and resistance to disappearing borders.',batch=2)],
reads=[dict(source_id=s,locator='Entire displayed Q&A'),dict(source_id=r,locator='Printed pp. 182–184'),dict(source_id=m,locator='Cover/record metadata only')],holds=['Breuilly and Hirschman lack individual endpoints. Full article, books and original conference talks unread.'])

p='judith_r_walkowitz';s='tq233_walkowitz_minerva'
P(p,
'A historian of gender, sexuality and urban life who joins cultural interpretation to material and social conditions. In her Minerva interview, Walkowitz recalls Hayden White’s supervision and his introduction of Foucault as resources for her research. She also identifies E. P. Thompson’s account of lived class formation as opening a route toward gender. Her use of Foucault is selective: she questions his attention to gender and leaves more room for individual and collective agency. The prostitution study examines regulation and feminist alliances; City of Dreadful Delight asks how sexual danger and possibility were narrated across a changing city. Walkowitz cautions that reading only its scandal-centred beginning and ending misses her attempt at a simultaneous, multilayered urban history. The Soho project extends that inquiry to contested cosmopolitan spaces, rather than treating the city as either an uncomplicated refuge or a single landscape of danger.',
'Substantial original Spanish Minerva interview by Julia Varela and Fernando Álvarez-Uría read in full as posted; issue 03, exact interview date not established and not inferred from web indexing. Author’s retrospective answers distinguished from interviewers’ suggested genealogies. Institutional bibliography retains publication dates. Complete books and cited White/Foucault/Thompson originals unread. Intellectual resources are specific; her explicit refusal of a general Foucauldian identity remains.',
sources=[S(s,'Julia Varela and Fernando Álvarez-Uría, “La voz de los archivos: Entrevista con Judith R. Walkowitz,” Minerva 03.','https://minerva.circulobellasartes.com/la-voz-de-los-archivos-entrevista-con-judith-r-walkowitz/','Entire displayed Spanish interview read from original journal publisher; local text receipt retained. Formation, named resources, Foucault qualification, archive method, urban simultaneity and reception self-critique. Exact interview/publication date not established; complete books unread.')],
edges=[E(p,'white','white',p,'Walkowitz credits White’s supervision and openness to unconventional research with supporting her inquiry into feminism and prostitution.',s,'First formation answer; she identifies particular teaching and reading mediation. Retrospective testimony, not wholesale agreement with narrative theory.',kind='influence'),E(p,'thompson','ep_thompson',p,'Walkowitz uses Thompson’s lived, cultural account of class as a route toward including gender and domestic life.',s,'Own answer to whether a book mattered for her formation. Specific resource in Making of the English Working Class; original book not newly read.'),E(p,'foucault',p,'foucault','Walkowitz qualifies her use of Foucault by demanding greater attention to gender, agency and historical change.',s,'Own answer to genealogy question: acknowledges reading/use, rejects a general Foucauldian label, states the methodological differences. Not wholesale rejection.',kind='critique')],
replacements=[R(p,3,p,'urbanhistory','Studies how spaces shape social actors and how those actors transform spaces, while seeking narrative forms for simultaneous urban processes.',s,'Own Soho and City of Dreadful Delight answers. Explicit methodological account, not an uncomplicated melting-pot interpretation.',batch=2)],
reads=[dict(source_id=s,locator='Entire posted interview; formation, theory, spatial method and reception answers')],holds=['Interviewers’ suggested Castel/Bourdieu/Donzelot genealogy is not Walkowitz’s acknowledgement and gets no edge. Complete monographs unread.'])

p='paul_kennedy';s='tq233_kennedy_roundtable2026'
P(p,
'A historian of international power who connects economic resources with military commitments and the changing position of states. In his roundtable response, Kennedy traces one stimulus for The Rise and Fall of the Great Powers through Mahan’s use of an earlier reflection on Spain’s scattered empire. He situates unequal growth within a broad historical problem rather than claiming every great-power change has one mechanical cause. Varsha Venkatasubramanian nevertheless challenges the book’s treatment of nonstate actors and the reverse effects of politics on economic development. Kennedy accepts her criticism of India’s limited treatment and concedes that the book may contain too much economic determinism. His 2009 Yale discussion supplies a separate question about institutions and states’ choices. The account therefore preserves both the explanatory programme and the author’s later qualifications instead of presenting the book as a confirmed prediction of national decline.',
'2026 scholarly roundtable: selected Venkatasubramanian critique and Kennedy’s response read, especially own stimulus and concessions; remaining contributors not treated as fully read. Earlier 2009 panel scopes retained. Complete selected books, Mahan and Campbell originals unread. Contemporary projections remain attributed and are not certified economic facts. Kennedy distinguishes publication-year 1987 from initial appearance at the beginning of 1988; earlier metadata discrepancy is thereby qualified.',
sources=[S(s,'H-Diplo/RJISSF Roundtable 18-2 on The Rise and Fall of the Great Powers, 11 September 2026: Venkatasubramanian and Kennedy.','https://issforum.org/roundtables/roundtable-18-2-on-kennedy-the-rise-and-fall-of-the-great-powers','Selected Venkatasubramanian methodological critique (paragraphs beginning Nevertheless and There is, however, another side) and Kennedy response on sources and concessions read. Other contributions not fully read. Original 1987 publication-year/early-1988 appearance distinguished in author’s closing paragraph. Local request denied; successful web text only, no local full receipt claimed.')],
edges=[E(p,'mahan','wartradition',p,'Kennedy identifies Mahan’s use of Campbell on Spain’s dispersed resources as one stimulus for the great-powers inquiry.',s,'Own response, opening stimulus discussion, nn. 94–95. Endpoint is the explicitly named strategic tradition, not an invented Mahan person node; quoted source originals unread.')],
replacements=[R(p,3,p,'military','Examines how military commitments interact with productive resources and changing state power, while later acknowledging limits of an overly economic explanation.',s,'Author’s response on unequal growth and concession concerning domestic politics/ideology. Venkatasubramanian’s criticism remains beside the programme.',batch=2)],
reads=[dict(source_id=s,locator='Selected critique and author response; stimulus, India, domestic politics and publication-date paragraphs')],holds=['Venkatasubramanian and Mahan lack individual endpoints. Her use of Polanyi is not reassigned to Kennedy; forecasts not independently verified.'])
